#!/usr/bin/env bash
set -uo pipefail
B=/home/azureuser/trading_corp
TAG=pre-pm-weekly-refresh-20260517-1730
TS=$(date -u +%Y%m%dT%H%M%SZ)

echo "=== 1. Pre-flight md5 ==="
md5sum $B/trading_corp/data/polymarket_data_api_client.py
md5sum $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py

echo
echo "=== 2. Backup .py files with tag $TAG ==="
cp $B/trading_corp/data/polymarket_data_api_client.py $B/trading_corp/data/polymarket_data_api_client.py.$TAG
cp $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py.$TAG
ls -la $B/trading_corp/data/polymarket_data_api_client.py.$TAG $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py.$TAG

echo
echo "=== 3. Decode patch ==="
PATCHFILE=/tmp/pm_weekly_refresh_$TS.patch
echo '' | base64 -d | gunzip > $PATCHFILE
wc -l $PATCHFILE

echo
echo "=== 4. patch --dry-run -p1 (verify clean apply) ==="
cd $B
if patch --dry-run -p1 -i $PATCHFILE 2>&1; then
  echo "DRY-RUN OK"
else
  echo "DRY-RUN FAILED — aborting before any real changes"
  exit 1
fi

echo
echo "=== 5. patch -p1 (apply for real) ==="
if patch -p1 -i $PATCHFILE 2>&1; then
  echo "APPLY OK"
else
  echo "APPLY FAILED — rolling back from backup tag"
  cp $B/trading_corp/data/polymarket_data_api_client.py.$TAG $B/trading_corp/data/polymarket_data_api_client.py
  cp $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py.$TAG $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py
  exit 1
fi

echo
echo "=== 6. Post-patch md5 + line count ==="
md5sum $B/trading_corp/data/polymarket_data_api_client.py
wc -l $B/trading_corp/data/polymarket_data_api_client.py
md5sum $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py
wc -l $B/trading_corp/scripts/seed_polymarket_watchlist_deep.py

echo
echo "=== 7. Smoke test: import + grep for new symbols ==="
$B/venv/bin/python -c "from trading_corp.data.polymarket_data_api_client import PolymarketDataAPIClient, PolymarketRateLimitError, _is_cloudflare_block, _CLOUDFLARE_RETRY_DELAYS_SEC; print('import OK; delays=', _CLOUDFLARE_RETRY_DELAYS_SEC)"
$B/venv/bin/python -c "from trading_corp.scripts.seed_polymarket_watchlist_deep import _merge_watchlists; print('merge OK')"

echo
echo "=== 8. CLI --help shows new flags ==="
$B/venv/bin/python -m trading_corp.scripts.seed_polymarket_watchlist_deep --help | grep -E "merge|max-total"

echo
echo "=== 9. Write systemd units ==="
echo ''   | base64 -d | sudo tee /etc/systemd/system/trading-corp-pm-watchlist-deep.service >/dev/null
echo '' | base64 -d | sudo tee /etc/systemd/system/trading-corp-pm-watchlist-deep.timer   >/dev/null
ls -la /etc/systemd/system/trading-corp-pm-watchlist-deep.*

echo
echo "=== 10. daemon-reload + enable --now timer ==="
sudo systemctl daemon-reload
sudo systemctl enable --now trading-corp-pm-watchlist-deep.timer
echo -n "enabled: "; systemctl is-enabled trading-corp-pm-watchlist-deep.timer
echo -n "active:  "; systemctl is-active  trading-corp-pm-watchlist-deep.timer

echo
echo "=== 11. Verify next-fire is Sun 2026-05-24 13:00 UTC (+ up to 15 min jitter) ==="
systemctl list-timers trading-corp-pm-watchlist-deep.timer --no-pager | head -3

echo
echo "=== DONE ==="
